@extends('layouts.app') @section('heading',$account->exists?'Edit account':'Create account') @section('content')<form class="card form-grid" method="post" action="{{ $account->exists?route('users.update',$account):route('users.store') }}">@csrf @if($account->exists)@method('PUT')@endif<label>First name<input name="first_name" value="{{ old('first_name',$account->first_name) }}" required></label><label>Last name<input name="last_name" value="{{ old('last_name',$account->last_name) }}" required></label><label>Email<input type="email" name="email" value="{{ old('email',$account->email) }}" required></label><label>Phone<input name="phone" value="{{ old('phone',$account->phone) }}"></label><label>Role<select name="role"><option value="cashier" @selected(old('role',$account->role)==='cashier')>Cashier</option><option value="admin" @selected(old('role',$account->role)==='admin')>Administrator</option></select></label><label>Status<select name="status"><option value="active" @selected(old('status',$account->status??'active')==='active')>Active</option><option value="inactive" @selected(old('status',$account->status)==='inactive')>Inactive</option></select></label><label>Password<input type="password" name="password" @required(!$account->exists)><small>{{ $account->exists?'Leave blank to keep the current password.':'At least 8 characters.' }}</small></label><label>Confirm password<input type="password" name="password_confirmation" @required(!$account->exists)></label><div class="full row"><button class="btn primary">Save account</button><a class="btn" href="{{ route('users.index') }}">Cancel</a></div></form>@endsection
